import { hexRgb, rgbToHex } from '@mintlify/common/colors';
const CHROMA_STEP = 0.002;
const GAMUT_EPSILON = 1e-4;
const toLinear = (channel) => {
    const value = channel / 255;
    return value <= 0.04045 ? value / 12.92 : Math.pow(((value + 0.055) / 1.055), 2.4);
};
const fromLinear = (value) => {
    const clamped = Math.min(1, Math.max(0, value));
    const encoded = clamped <= 0.0031308 ? clamped * 12.92 : 1.055 * Math.pow(clamped, (1 / 2.4)) - 0.055;
    return Math.round(encoded * 255);
};
export const toOklch = (hex) => {
    const { red, green, blue } = hexRgb(hex);
    const [r, g, b] = [toLinear(red), toLinear(green), toLinear(blue)];
    const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
    const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
    const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
    const lightness = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s;
    const a = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
    const bAxis = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;
    const hue = (Math.atan2(bAxis, a) * 180) / Math.PI;
    return { l: lightness, c: Math.hypot(a, bAxis), h: (hue + 360) % 360 };
};
const toLinearRgb = ({ l, c, h }) => {
    const radians = (h * Math.PI) / 180;
    const a = c * Math.cos(radians);
    const b = c * Math.sin(radians);
    const lCube = Math.pow((l + 0.3963377774 * a + 0.2158037573 * b), 3);
    const mCube = Math.pow((l - 0.1055613458 * a - 0.0638541728 * b), 3);
    const sCube = Math.pow((l - 0.0894841775 * a - 1.291485548 * b), 3);
    return [
        4.0767416621 * lCube - 3.3077115913 * mCube + 0.2309699292 * sCube,
        -1.2684380046 * lCube + 2.6097574011 * mCube - 0.3413193965 * sCube,
        -0.0041960863 * lCube - 0.7034186147 * mCube + 1.707614701 * sCube,
    ];
};
const isInGamut = (color) => toLinearRgb(color).every((value) => value >= -GAMUT_EPSILON && value <= 1 + GAMUT_EPSILON);
export const oklchToHex = (color) => {
    let chroma = color.c;
    while (chroma > 0 && !isInGamut(Object.assign(Object.assign({}, color), { c: chroma })))
        chroma -= CHROMA_STEP;
    const [red, green, blue] = toLinearRgb(Object.assign(Object.assign({}, color), { c: Math.max(0, chroma) }));
    return rgbToHex({ r: fromLinear(red), g: fromLinear(green), b: fromLinear(blue), a: 1 });
};
